  JsonArray rows=new JsonArray();for(int i=0;i<CASES.length;i++){NBTTagCompound raw=JsonToNBT.getTagFromJson(CASES[i]);TileEntityProgrammableStorage tile=new TileEntityProgrammableStorage();tile.readFromNBT(raw.copy());ItemStack finalStack=tile.getStackInSlot(0);JsonObject row=new JsonObject();row.addProperty("input",CASES[i]);row.addProperty("ambiguous",i<5);row.addProperty("final",finalStack.writeToNBT(new NBTTagCompound()).toString());if(i==4||i==6){net.minecraft.util.NonNullList<ItemStack> children=net.minecraft.util.NonNullList.withSize(27,ItemStack.EMPTY);net.minecraft.inventory.ItemStackHelper.loadAllItems(finalStack.getSubCompound("BlockEntityTag"),children);row.addProperty("nestedFinal",children.get(0).writeToNBT(new NBTTagCompound()).toString());if(children.get(0).getItem()!=net.minecraft.init.Items.IRON_INGOT||children.get(0).getCount()!=3)throw new AssertionError("actual nested last-wins");}else if(i!=1&&(finalStack.getItem()!=net.minecraft.init.Items.IRON_INGOT||finalStack.getCount()!=3))throw new AssertionError("actual Storage last-wins "+i);rows.add(row);}
